testHooks.gateway = gateway;
// [FS-MOMENTS] 朋友圈 B 方案：文案由 dsh 读 persona.json 生成，鲸鱼只当「手」发表。
// 鲸鱼侧须 publishFeatureEnabled=true（总开关）且 publishEnabled=false（原生定时关掉），
// 否则会出现「鲸鲸口吻」的第二条人格在发朋友圈。节奏看 wechat.moments 段。
try {
	const moments = createMoments({
		getConfig,
		saveConfig,
		log,
		callLlm: llmRouter.bound('social'),
		personaPath: () => `${fishSoulDir()}/persona.json`,
	});
	moments.start();
	ctx.effect(() => () => moments.stop(), 'dsh-fish-soul: moments');
} catch (error) {
	log('warn', `[fish-soul] 朋友圈模块没装上：${String(error instanceof Error ? error.message : error)}`);
}
